    const html = call('exBlockHTML', 0, { name: OV_EX, inc: 5, repMode: 'str' }, 'ok');
    ok('Today tab shows locked 145, not the earned 150', html.indexOf('145 lb') >= 0 && html.indexOf('150 lb') === -1, html.slice(0, 300));

