    ok('spike guard: e1Spike names both numbers', (function(){ const x = ev('e1Spike(historyFor("Zz Spike Press"))'); return x && x.cur > x.base * 1.08; })());
    // Backed up: the next session reaches the same level, so the jump goes ahead.
