    ev("S.logs = " + JSON.stringify([{id: 993201, date: pdk(-6), day: 'D2', entries: [{exercise: 'Zz Bound Row', sets: [{w: 160, r: hi - 4, e: 'grind'}, {w: 160, r: hi - 5, e: 'fail'}]}]}]) + ";");
