    ev("S.experiments.lastEnded = ''; expStart({template:'sleep', lift:null, range:null, sessions:4, hypothesis:" + JSON.stringify(hyp) + "}); S.experiments.active.startedAt = mesoAddDays(todayKey(), -30);");
